# SF issue names we ignore (normal patterns, not problems)
IGNORE_SF = {"H2: Multiple", "Meta Keywords: Missing", "Accessibility: Accessibility Score Good"}

SF_INDEX = {n: k for k, v in CATALOG.items() for n in v[5]}
SEM_INDEX = {n: k for k, v in CATALOG.items() for n in v[6]}


def entry(k):
    t, sev, pri, eff, grp, sfn, semn, why, fixk, fixe = CATALOG[k]
    return dict(id=k, title=t, severity=sev, priority=pri, effort=eff, group=grp, sf=sfn, semrush=semn, why=why, fix_key=fixk, fix_expert=fixe)


def sf_generic(meta):
    """Severity for SF issues not in the catalog, from SF's own type/priority."""
    typ, pri = str(meta.get("Issue Type", "")), str(meta.get("Issue Priority", "Low"))
    sev = E if (typ == "Issue" and pri == "High") else (W if typ in ("Issue", "Warning") else N)
    return sev, pri if pri in ("High", "Medium", "Low") else "Low"


def sem_generic(typ):
    return {"ERROR": (E, "High"), "WARNING": (W, "Medium")}.get(typ, (N, "Low"))
